mapper.select:
SELECT id, user_id AS userId, original_name AS originalName, public_url AS publicUrl, verdict, score, DATE_FORMAT(reg_dt, '%Y-%m-%d %H:%i:%s') AS regDt FROM verification
verdict = #{verdict}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

mapper.delete:
DELETE FROM verification
WHERE id = #{id}
  AND user_id = #{userId}
